html:
{% macro fmt_num(v) -%}
{{ ('%.3f'|format(v or 0)).rstrip('0').rstrip('.') }}
{%- endmacro %}

{% macro inr(value) -%}
{%- set v = value or 0 -%}
{%- set s = '%.2f'|format(v|abs) -%}
{%- set whole, frac = s.split('.') -%}
{%- set ns = namespace(txt=whole) -%}
{%- if whole|length > 3 -%}
{%- set ns.txt = '' -%}
{%- for ch in whole[:-3]|reverse -%}
{%- if loop.index0 > 0 and loop.index0 % 2 == 0 -%}{%- set ns.txt = ',' ~ ns.txt -%}{%- endif -%}
{%- set ns.txt = ch ~ ns.txt -%}
{%- endfor -%}
{%- set ns.txt = ns.txt ~ ',' ~ whole[-3:] -%}
{%- endif -%}
{{- '-' if v < 0 else '' -}}{{- ns.txt -}}{{- ('.' ~ frac) if frac != '00' else '' -}}/-
{%- endmacro %}

<style>
  .dc-table { width:100%; border-collapse: collapse; font-family: Arial, sans-serif; font-size: 10px; }
  .dc-table td, .dc-table th { border: 1px solid #000; padding: 4px 6px; vertical-align: top; }
  .dc-label { font-weight:bold; }
  .dc-right { text-align:right; white-space:nowrap; }
  .dc-center { text-align:center; }
  .dc-copy-label { text-align:center; font-weight:bold; font-size:11px; padding:4px; background:#f0f0f0; }
</style>

{% macro render_challan(copy_label) %}
<div class="dc-copy-label">DELIVERY CHALLAN {{ copy_label }}</div>

<table class="dc-table">
  <tr>
    <td style="width:50%;">
      <strong>FROM</strong><br>
      <strong>RISHAB INDUSTRIES</strong><br>
      Unit-1, Plot No. 57/7, Sector No. 10, PCNTDA, Near Times of India, Bhosari, Pune-411026<br>
      GSTIN : {{ doc.company_gstin }}<br>
      State Name : Maharashtra, Code : 27<br>
      Email : jagmohan@rishabindustries.co.in
    </td>
    <td style="width:50%;">
      Challan No. : <strong>{{ doc.name }}</strong><br>
      Challan Date : <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</strong><br>
      Challan Type : <strong>{{ doc.get("challan_type") or "" }}</strong><br>
      Ref. No. : {{ doc.po_no or '' }}<br>
      Ref. Date : {{ frappe.utils.formatdate(doc.po_date, "dd-MM-yyyy") if doc.po_date else '' }}<br>
      Your Ref. No. :<br>
      Your Ref. Date :
    </td>
  </tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr>
    <td>
      TO (Ship To)<br>
      <strong>{{ doc.customer_name }}</strong><br>
      {{ doc.shipping_address or doc.address_display or '' }}<br>
      Ph No. : {{ doc.get("contact_phone") or doc.get("contact_mobile") or "" }}<br>
      GSTIN : {{ doc.billing_address_gstin or '' }}<br>
      State Name : 27 MAHARASHTRA
    </td>
  </tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr><td>Terms of Delivery/ Remarks : {{ doc.terms or '' }}</td></tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr>
    <th style="width:4%;">Sr</th>
    <th>Item No./ Description/ Purpose/Details</th>
    <th style="width:9%;">HSN /SAC</th>
    <th style="width:9%;">Quantity</th>
    <th style="width:6%;">UOM</th>
    <th style="width:10%;">Rate</th>
    <th style="width:6%;">Disc %</th>
    <th style="width:12%;">Amount</th>
  </tr>

  {% set uom_totals = {} %}
  {% set wt = namespace(v=0) %}
  {% for item in doc.items %}
  {% set _ = uom_totals.update({item.uom: uom_totals.get(item.uom, 0) + item.qty}) %}
  {% set wt.v = wt.v + (item.get("total_weight") or 0) %}
  {% set d = item.description or item.item_name or '' %}
  <tr>
    <td class="dc-center">{{ loop.index }}</td>
    <td>
      {{ d }}<br>
      {% if d != item.item_code %}{{ item.item_code }}<br>{% endif %}
      Purpose / Details :
    </td>
    <td class="dc-center">{{ item.gst_hsn_code or '' }}</td>
    <td class="dc-right">{{ "%.2f"|format(item.qty) }}</td>
    <td class="dc-center">{{ item.uom }}</td>
    <td class="dc-right">{{ inr(item.rate) }}</td>
    <td class="dc-right">{{ "%.2f"|format(item.discount_percentage or 0) }}</td>
    <td class="dc-right">{{ inr(item.amount) }}</td>
  </tr>
  {% endfor %}

  {% set total_wt = doc.get("total_weight_kg") or doc.get("total_net_weight") or wt.v %}
  <tr>
    <td></td>
    <td colspan="7" class="dc-label">
      TOTAL QTY - {% for u, q in uom_totals.items() %}{{ fmt_num(q) }} {{ u | upper }}{% if not loop.last %}, {% endif %}{% endfor %}
      &nbsp;&nbsp;&nbsp;&nbsp;
      TOTAL WT. - {{ "%.3f"|format(total_wt) }} KG
    </td>
  </tr>

  {% for tax in doc.taxes | sort(attribute='description') %}
  <tr>
    <td colspan="7" class="dc-right">{{ tax.description }} {{ fmt_num(tax.rate) }}%</td>
    <td class="dc-right">{{ inr(tax.tax_amount) }}</td>
  </tr>
  {% endfor %}

  {% if doc.rounding_adjustment %}
  <tr>
    <td colspan="7" class="dc-right"><i>Less :</i> <strong>Amount Rounded Off</strong></td>
    <td class="dc-right">{{ inr(doc.rounding_adjustment) }}</td>
  </tr>
  {% endif %}

  <tr>
    <td colspan="7" class="dc-right dc-label">Total</td>
    <td class="dc-right dc-label">{{ inr(doc.rounded_total or doc.grand_total) }}</td>
  </tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr><td>Amount Chargeable (in words) :<br><strong>{{ doc.in_words }}</strong></td></tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr>
    <td style="width:50%;">
      Department : {{ doc.get("dc_department") or "" }}<br>
      Transporter : {{ doc.get("transporter_name") or doc.get("transporter") or "" }}<br>
      Ref. Person : {{ doc.get("dc_ref_person") or "" }}<br>
      Vehicle No. : {{ doc.get("vehicle_no") or "" }}<br>
      Prepared By : {{ frappe.db.get_value("User", doc.owner, "full_name") }}
    </td>
    <td style="width:50%; text-align:right; vertical-align:bottom;">
      <strong>FOR RISHAB INDUSTRIES</strong><br><br><br>
      Authorised Signatory
    </td>
  </tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr>
    <td style="width:50%;">
      Received In Good Condition<br>
      Date :<br>
      Place :
    </td>
    <td style="width:50%;">
      Signature of Processor/Receiver Name of Factory &amp; Address
    </td>
  </tr>
</table>

<table class="dc-table" style="margin-top:0;">
  <tr>
    <th rowspan="2">HSN/SAC</th>
    <th rowspan="2">Taxable<br>Value</th>
    <th colspan="2">CentralTax</th>
    <th colspan="2">StateTax</th>
    <th colspan="2">IntegratedTax</th>
    <th rowspan="2">Total Tax<br>Amount</th>
  </tr>
  <tr>
    <th>Rate</th><th>Amount</th>
    <th>Rate</th><th>Amount</th>
    <th>Rate</th><th>Amount</th>
  </tr>

  {% set hsn_map = {} %}
  {% for item in doc.items %}
    {% set hsn = item.gst_hsn_code or '' %}
    {% if hsn not in hsn_map %}
      {% set _ = hsn_map.update({hsn: {'taxable': 0, 'cgst_rate': 0, 'cgst_amt': 0, 'sgst_rate': 0, 'sgst_amt': 0, 'igst_rate': 0, 'igst_amt': 0}}) %}
    {% endif %}
    {% set _ = hsn_map[hsn].update({'taxable': hsn_map[hsn]['taxable'] + item.amount}) %}
  {% endfor %}

  {% for tax in doc.taxes %}
    {% for item in doc.items %}
      {% set hsn = item.gst_hsn_code or '' %}
      {% if 'CGST' in tax.description %}
        {% set _ = hsn_map[hsn].update({'cgst_rate': tax.rate, 'cgst_amt': hsn_map[hsn]['cgst_amt'] + (item.amount * tax.rate / 100)}) %}
      {% elif 'SGST' in tax.description %}
        {% set _ = hsn_map[hsn].update({'sgst_rate': tax.rate, 'sgst_amt': hsn_map[hsn]['sgst_amt'] + (item.amount * tax.rate / 100)}) %}
      {% elif 'IGST' in tax.description %}
        {% set _ = hsn_map[hsn].update({'igst_rate': tax.rate, 'igst_amt': hsn_map[hsn]['igst_amt'] + (item.amount * tax.rate / 100)}) %}
      {% endif %}
    {% endfor %}
  {% endfor %}

  {% set totals = namespace(taxable=0, cgst=0, sgst=0, igst=0) %}
  {% for hsn, vals in hsn_map.items() %}
  {% set totals.taxable = totals.taxable + vals.taxable %}
  {% set totals.cgst = totals.cgst + vals.cgst_amt %}
  {% set totals.sgst = totals.sgst + vals.sgst_amt %}
  {% set totals.igst = totals.igst + vals.igst_amt %}
  <tr>
    <td class="dc-center">{{ hsn }}</td>
    <td class="dc-right">{{ inr(vals.taxable) }}</td>
    <td class="dc-center">{{ fmt_num(vals.cgst_rate) }}</td>
    <td class="dc-right">{{ inr(vals.cgst_amt) }}</td>
    <td class="dc-center">{{ fmt_num(vals.sgst_rate) }}</td>
    <td class="dc-right">{{ inr(vals.sgst_amt) }}</td>
    <td class="dc-center">{{ fmt_num(vals.igst_rate) }}</td>
    <td class="dc-right">{{ inr(vals.igst_amt) }}</td>
    <td class="dc-right">{{ inr(vals.cgst_amt + vals.sgst_amt + vals.igst_amt) }}</td>
  </tr>
  {% endfor %}

  <tr class="dc-label">
    <td class="dc-right">Total</td>
    <td class="dc-right">{{ inr(totals.taxable) }}</td>
    <td></td><td class="dc-right">{{ inr(totals.cgst) }}</td>
    <td></td><td class="dc-right">{{ inr(totals.sgst) }}</td>
    <td></td><td class="dc-right">{{ inr(totals.igst) }}</td>
    <td class="dc-right">{{ inr(totals.cgst + totals.sgst + totals.igst) }}</td>
  </tr>
</table>
{% endmacro %}

{% set copies = ["ORIGINAL FOR CONSIGNEE", "DUPLICATE FOR TRANSPORTER", "TRIPLICATE FOR SUPPLIER"] %}
{% for label in copies %}
{{ render_challan(label) }}
{% if not loop.last %}<div style="page-break-after: always;"></div>{% endif %}
{% endfor %}
